-- =====================================================================
-- AppFinances database init script
-- Target: PostgreSQL
--
-- Generated by tracing every SQL statement in
-- AppFinancesClassLibrary/Infrastructure/Repositories against the
-- entities/DTOs they read and write, so column names, nullability and
-- types match what the application code actually sends and expects
-- back from Dapper.
--
-- Run once against an empty database, e.g.:
--   psql "postgresql://USER:PASSWORD@HOST:5432/appfinances" -f init.sql
-- =====================================================================

-- Every ID is a sequential BIGINT generated by the database
-- (GENERATED ALWAYS AS IDENTITY): the app never sends IDs on INSERT.

-- =====================================================================
-- USERS
-- Backs UserEntity / UserRepository.
-- Named USERS (not the singular USER) because USER is a reserved
-- keyword in PostgreSQL and cannot be used unquoted as a table name.
-- =====================================================================
CREATE TABLE USERS (
    ID          BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    NAME        TEXT NOT NULL,
    SURNAME     TEXT NOT NULL,
    BIRTHDATE   DATE NOT NULL,
    EMAIL       TEXT NOT NULL,
    PHONE       TEXT,
    ACTIVE      BOOLEAN NOT NULL DEFAULT TRUE,
    DELETED_AT  TIMESTAMPTZ,
    CREATED_AT  TIMESTAMPTZ NOT NULL DEFAULT now(),
    UPDATED_AT  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Deleting a user is a soft delete (ACTIVE = false): email and phone only
-- have to be unique among active users, so a deleted user's data can be
-- registered again.
CREATE UNIQUE INDEX UX_USERS_EMAIL_ACTIVE ON USERS(EMAIL) WHERE ACTIVE;
CREATE UNIQUE INDEX UX_USERS_PHONE_ACTIVE ON USERS(PHONE) WHERE ACTIVE;

-- =====================================================================
-- AUTHENTICATION
-- Backs AuthenticationEntity / AuthenticationRepository.
-- ROLE stores the UserRole enum ordinal (user = 0, admin = 1) since
-- the app passes the enum straight to Dapper without stringifying it.
-- =====================================================================
CREATE TABLE AUTHENTICATION (
    ID             BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    USER_ID        BIGINT NOT NULL REFERENCES USERS(ID),
    USERNAME       TEXT NOT NULL,
    PASSWORD_HASH  TEXT NOT NULL,
    ROLE           INTEGER NOT NULL DEFAULT 0,
    ACTIVE         BOOLEAN NOT NULL DEFAULT TRUE,
    LAST_LOGIN     TIMESTAMPTZ NOT NULL DEFAULT now(),
    CREATED_AT     TIMESTAMPTZ NOT NULL DEFAULT now(),
    UPDATED_AT     TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (USER_ID)
);

-- Mirrors USERS.ACTIVE (kept in sync by UserRepository.DeleteAsync), since a
-- partial index can't look at another table: the username only has to be
-- unique among active users.
CREATE UNIQUE INDEX UX_AUTHENTICATION_USERNAME_ACTIVE ON AUTHENTICATION(USERNAME) WHERE ACTIVE;

-- =====================================================================
-- BANK_ACCOUNTS
-- Backs BankAccountsEntity / BankAccountsRepository.
-- =====================================================================
CREATE TABLE BANK_ACCOUNTS (
    ID              BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    USER_ID         BIGINT NOT NULL REFERENCES USERS(ID),
    BANK_NAME       TEXT NOT NULL,
    AGENCY          TEXT,
    ACCOUNT_NUMBER  TEXT,
    IS_DEFAULT      BOOLEAN NOT NULL DEFAULT FALSE,
    BALANCE_CENTS   INTEGER NOT NULL DEFAULT 0,
    CREATED_AT      TIMESTAMPTZ NOT NULL DEFAULT now(),
    UPDATED_AT      TIMESTAMPTZ NOT NULL DEFAULT now(),
    ACTIVE          BOOLEAN NOT NULL DEFAULT TRUE,
    DELETED_AT      TIMESTAMPTZ
);

-- =====================================================================
-- CATEGORIES
-- Backs CategoriesEntity / CategoriesRepository.
-- TYPE stores the CategoriesTypes enum ordinal (Entrada = 0, Saida = 1).
-- IS_DEFAULT marks the system "Metas" category, created by UserService on
-- signup: transactions in it must reference a goal (META_ID). Each user
-- has exactly one; it cannot be created through the API nor deleted.
-- =====================================================================
CREATE TABLE CATEGORIES (
    ID                BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    USER_ID           BIGINT NOT NULL REFERENCES USERS(ID),
    NAME              TEXT NOT NULL,
    TYPE              INTEGER NOT NULL,
    IS_DEFAULT        BOOLEAN NOT NULL DEFAULT FALSE,
    LIMIT_VALUE_CENTS INTEGER NOT NULL DEFAULT 0,
    CREATED_AT        TIMESTAMPTZ NOT NULL DEFAULT now(),
    UPDATED_AT        TIMESTAMPTZ NOT NULL DEFAULT now(),
    ACTIVE            BOOLEAN NOT NULL DEFAULT TRUE,
    DELETED_AT        TIMESTAMPTZ
);

CREATE UNIQUE INDEX UX_CATEGORIES_ONE_DEFAULT_PER_USER ON CATEGORIES(USER_ID) WHERE IS_DEFAULT;

-- =====================================================================
-- CARDS
-- Backs CardsEntity / CardsRepository.
-- TYPE stores the CardsType enum ordinal (credito = 0, debito = 1).
-- CLOSING_DATE / DUE_DATE are day-of-month integers (1-31), not dates.
-- =====================================================================
CREATE TABLE CARDS (
    ID                BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    BANK_ACCOUNT_ID   BIGINT NOT NULL REFERENCES BANK_ACCOUNTS(ID),
    NAME              TEXT NOT NULL,
    TYPE              INTEGER NOT NULL,
    LIMIT_VALUE_CENTS INTEGER NOT NULL DEFAULT 0,
    CLOSING_DATE      INTEGER NOT NULL,
    DUE_DATE          INTEGER NOT NULL,
    CREATED_AT        TIMESTAMPTZ NOT NULL DEFAULT now(),
    UPDATED_AT        TIMESTAMPTZ NOT NULL DEFAULT now(),
    ACTIVE            BOOLEAN NOT NULL DEFAULT TRUE,
    DELETED_AT        TIMESTAMPTZ
);

-- =====================================================================
-- BANK_STATEMENTS
-- Backs BankStatementsEntity / BankStatementsRepository.
-- STATUS stores the BankStatementsStatus enum ordinal
-- (aberta = 0, fechada = 1, paga = 2, atrasada = 3).
-- =====================================================================
CREATE TABLE BANK_STATEMENTS (
    ID              BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    CARD_ID         BIGINT NOT NULL REFERENCES CARDS(ID),
    MONTH_REFERENCE TEXT NOT NULL,
    CLOSING_DATE    DATE NOT NULL,
    DUE_DATE        DATE NOT NULL,
    PAYMENT_DATE    DATE,
    STATUS          INTEGER NOT NULL DEFAULT 0,
    CREATED_AT      TIMESTAMPTZ NOT NULL DEFAULT now(),
    UPDATED_AT      TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (CARD_ID, MONTH_REFERENCE)
);

-- =====================================================================
-- BANK_STATEMENT_PAYMENTS
-- Backs BankStatementPayment / BankStatementsRepository.
-- Each payment of a credit card statement, taken out of the balance of
-- BANK_ACCOUNT_ID. A statement can be paid in parts: it turns "paga" when
-- the payments reach its total, and PAYMENT_DATE is then the date of the
-- payment that completed it.
-- =====================================================================
CREATE TABLE BANK_STATEMENT_PAYMENTS (
    ID                  BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    BANK_STATEMENT_ID   BIGINT NOT NULL REFERENCES BANK_STATEMENTS(ID),
    BANK_ACCOUNT_ID     BIGINT NOT NULL REFERENCES BANK_ACCOUNTS(ID),
    AMOUNT_CENTS        INTEGER NOT NULL CHECK (AMOUNT_CENTS > 0),
    PAYMENT_DATE        DATE NOT NULL,
    CREATED_AT          TIMESTAMPTZ NOT NULL DEFAULT now(),
    UPDATED_AT          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IX_BANK_STATEMENT_PAYMENTS_STATEMENT_ID ON BANK_STATEMENT_PAYMENTS(BANK_STATEMENT_ID);

-- =====================================================================
-- GOALS
-- Backs GoalsEntity / GoalsRepository.
-- =====================================================================
CREATE TABLE GOALS (
    ID                   BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    USER_ID              BIGINT NOT NULL REFERENCES USERS(ID),
    INICIAL_DATE         DATE NOT NULL,
    FINAL_DATE           DATE NOT NULL,
    INICIAL_VALUE_CENTS  INTEGER NOT NULL,
    FINAL_VALUE_CENTS    INTEGER NOT NULL,
    DESCRIPTION          TEXT NOT NULL,
    CREATED_AT           TIMESTAMPTZ NOT NULL DEFAULT now(),
    UPDATED_AT           TIMESTAMPTZ NOT NULL DEFAULT now(),
    ACTIVE               BOOLEAN NOT NULL DEFAULT TRUE,
    DELETED_AT           TIMESTAMPTZ
);

-- =====================================================================
-- TRANSACTIONS
-- Backs TransactionsEntity / TransactionsRepository.
-- PAYMENT_METHOD stores PaymentMethod ordinal
--   (cartao_credito=0, cartao_debito=1, dinheiro=2, pix=3, boleto=4).
-- SOURCE stores TransactionSource ordinal (manual=0, ocr=1, imported=2).
-- CARD_ID / BANK_ACCOUNT_ID / BANK_STATEMENT_ID / META_ID are nullable:
-- exactly one of CARD_ID or BANK_ACCOUNT_ID is populated depending on
-- PAYMENT_METHOD, BANK_STATEMENT_ID only applies to credit-card
-- transactions, and META_ID only applies to contributions to a goal.
-- =====================================================================
CREATE TABLE TRANSACTIONS (
    ID                  BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    USER_ID             BIGINT NOT NULL REFERENCES USERS(ID),
    CATEGORY_ID         BIGINT NOT NULL REFERENCES CATEGORIES(ID),
    META_ID             BIGINT REFERENCES GOALS(ID),
    -- Set exactly when META_ID is (CHECK below): the Metas category has a single fixed Type
    -- (Saida), so this is what tells a deposit toward the goal apart from a withdrawal out of
    -- it. 0 = deposito, 1 = retirada (GoalContributionDirection enum ordinal).
    META_DIRECTION      INTEGER,
    CARD_ID             BIGINT REFERENCES CARDS(ID),
    BANK_ACCOUNT_ID     BIGINT REFERENCES BANK_ACCOUNTS(ID),
    BANK_STATEMENT_ID   BIGINT REFERENCES BANK_STATEMENTS(ID),
    DESCRIPTION         TEXT NOT NULL,
    PAYMENT_METHOD      INTEGER NOT NULL,
    PAYMENT_PARCELS     INTEGER NOT NULL DEFAULT 1,
    PAYMENT_VALUE_CENTS INTEGER NOT NULL CHECK (PAYMENT_VALUE_CENTS > 0),
    PAYMENT_VALUE_OCR   INTEGER,
    DESCRIPTION_OCR     TEXT,
    RECORRENT           BOOLEAN NOT NULL DEFAULT FALSE,
    RECORRENT_MONTHS    INTEGER,
    RECORRENT_SERIAL_ID BIGINT,
    TRANSACTION_DATE    DATE NOT NULL,
    PAYMENT_DATE        DATE,
    EXPIRING_DATE       DATE,
    SOURCE              INTEGER NOT NULL DEFAULT 0,
    -- FALSE only when the category came from the automatic classifier and the
    -- user accepted it unchanged; reclassification never touches TRUE rows.
    CATEGORY_CONFIRMED_MANUALLY BOOLEAN NOT NULL DEFAULT TRUE,
    ACTIVE              BOOLEAN NOT NULL DEFAULT TRUE,
    DELETED_AT          TIMESTAMPTZ,
    CREATED_AT          TIMESTAMPTZ NOT NULL DEFAULT now(),
    UPDATED_AT          TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK ((META_ID IS NULL) = (META_DIRECTION IS NULL))
);

-- RECORRENT_SERIAL_ID groups the installments/occurrences of one recurring
-- series. It is not a row ID, so it comes from its own sequence, taken by
-- TransactionsRepository.NextRecorrentSerialIdAsync before the rows exist.
CREATE SEQUENCE TRANSACTIONS_RECORRENT_SERIAL_SEQ AS BIGINT;

CREATE INDEX IX_TRANSACTIONS_USER_ID ON TRANSACTIONS(USER_ID) WHERE DELETED_AT IS NULL;
CREATE INDEX IX_TRANSACTIONS_RECORRENT_SERIAL_ID ON TRANSACTIONS(RECORRENT_SERIAL_ID);

-- =====================================================================
-- DOCUMENTS
-- Backs DocumentsEntity / DocumentsRepository.
-- TRANSACTION_ID is nullable: NULL until the OCR/confirmação flow
-- creates the transaction, matching Documents.TransactionId (long?)
-- in the application. Only assigned afterwards, via UpdateTransactionAsync.
-- STATUS stores StatusOCRTypes ordinal (pendente=0, processado=1, erro=2).
-- =====================================================================
CREATE TABLE DOCUMENTS (
    ID                  BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    USER_ID             BIGINT NOT NULL REFERENCES USERS(ID),
    TRANSACTION_ID      BIGINT REFERENCES TRANSACTIONS(ID),
    DOCUMENT_URL        TEXT NOT NULL,
    TEXT_OCR            TEXT NOT NULL,
    TRUST_OCR           NUMERIC(5,4) NOT NULL,
    -- Lowest confidence among the digits of the payment value; NULL when
    -- no value was found. TRUST_OCR averages the whole image.
    VALUE_TRUST_OCR     NUMERIC(5,4),
    STATUS              INTEGER NOT NULL DEFAULT 0,
    CONFIRMED_MANUALLY  BOOLEAN NOT NULL DEFAULT FALSE,
    -- Key generated by the app when the photo is taken: resending the same
    -- photo returns the existing document instead of creating another.
    IDEMPOTENCY_KEY     TEXT,
    -- Deleting a document is a soft delete: the OCR text, its items and the
    -- stored image are kept.
    ACTIVE              BOOLEAN NOT NULL DEFAULT TRUE,
    DELETED_AT          TIMESTAMPTZ,
    -- Processing time, apart from UPDATED_AT (overwritten by the confirmation):
    -- CREATED_AT -> OCR_STARTED_AT is the queue wait, OCR_STARTED_AT ->
    -- OCR_FINISHED_AT is the reading. OCR_FINISHED_AT is NULL when it failed.
    OCR_STARTED_AT      TIMESTAMPTZ,
    OCR_FINISHED_AT     TIMESTAMPTZ,
    -- Main activity (CNAE, 7 digits) of the store CNPJ read in the receipt,
    -- looked up once when the OCR finishes; NULL when there is no CNPJ or the
    -- lookup failed. Used to suggest the category.
    ESTABLISHMENT_CNAE  INTEGER,
    -- Registry name of that CNPJ (trade name, or legal name without one); the
    -- establishment when the OCR did not read it and the user history has none.
    ESTABLISHMENT_REGISTRY_NAME TEXT,
    CREATED_AT          TIMESTAMPTZ NOT NULL DEFAULT now(),
    UPDATED_AT          TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Only active documents block the key: the same photo can be sent again
-- after its document was deleted.
CREATE UNIQUE INDEX UX_DOCUMENTS_USER_IDEMPOTENCY_KEY
    ON DOCUMENTS (USER_ID, IDEMPOTENCY_KEY)
    WHERE IDEMPOTENCY_KEY IS NOT NULL AND ACTIVE;

-- =====================================================================
-- DOCUMENT_ITEMS
-- Backs DocumentItemsEntity / DocumentItemsRepository.
-- One row per line item the OCR read from the receipt, written right
-- after the OCR runs. TOTAL_CENTS is the printed line total, or
-- QUANTITY x UNIT_PRICE_CENTS when the OCR did not read it.
-- =====================================================================
CREATE TABLE DOCUMENT_ITEMS (
    ID                  BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    DOCUMENT_ID         BIGINT NOT NULL REFERENCES DOCUMENTS(ID) ON DELETE CASCADE,
    LINE_NUMBER         INTEGER NOT NULL,
    CODE                TEXT,
    DESCRIPTION         TEXT NOT NULL,
    QUANTITY            NUMERIC(12,3) NOT NULL,
    UNIT                TEXT,
    UNIT_PRICE_CENTS    INTEGER NOT NULL,
    TOTAL_CENTS         INTEGER NOT NULL,
    CREATED_AT          TIMESTAMPTZ NOT NULL DEFAULT now(),
    UPDATED_AT          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IX_DOCUMENT_ITEMS_DOCUMENT_ID ON DOCUMENT_ITEMS(DOCUMENT_ID);

-- =====================================================================
-- DOCUMENT_CONFIRMATIONS
-- Written by DocumentConfirmationsRepository when a document is confirmed.
-- What the OCR suggested next to what the user confirmed, one row per
-- confirmed document, so the OCR accuracy can be measured field by field.
-- SUGGESTED_* is NULL when the OCR could not read that field.
-- SUGGESTED_CATEGORY_REASON stores CategoryClassificationReason ordinal.
-- ITEMS_CONFIRMED is FALSE when the confirmation did not send the items
-- (the user did not review them): DOCUMENT_CONFIRMED_ITEMS stays empty.
-- ESTABLISHMENT_KEY identifies the store: the CNPJ (14 digits, check digits
-- valid) of the receipt header or of the Pix recipient, or "cpf:" plus the
-- six digits the masked CPF of a Pix recipient shows. NULL when not found.
-- With the transaction category it is the user history the classifier uses
-- for the next receipt of that store.
-- =====================================================================
CREATE TABLE DOCUMENT_CONFIRMATIONS (
    ID                              BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    DOCUMENT_ID                     BIGINT NOT NULL UNIQUE REFERENCES DOCUMENTS(ID),
    TRANSACTION_ID                  BIGINT NOT NULL REFERENCES TRANSACTIONS(ID),
    SUGGESTED_DESCRIPTION           TEXT,
    CONFIRMED_DESCRIPTION           TEXT NOT NULL,
    SUGGESTED_PAYMENT_VALUE_CENTS   INTEGER,
    CONFIRMED_PAYMENT_VALUE_CENTS   INTEGER NOT NULL,
    SUGGESTED_TRANSACTION_DATE      DATE,
    CONFIRMED_TRANSACTION_DATE      DATE NOT NULL,
    SUGGESTED_CATEGORY_ID           BIGINT REFERENCES CATEGORIES(ID),
    SUGGESTED_CATEGORY_REASON       INTEGER NOT NULL,
    CONFIRMED_CATEGORY_ID           BIGINT NOT NULL REFERENCES CATEGORIES(ID),
    SUGGESTED_ITEMS_TOTAL_CENTS     INTEGER,
    ITEMS_CONFIRMED                 BOOLEAN NOT NULL,
    ESTABLISHMENT_KEY               TEXT,
    -- Where SUGGESTED_DESCRIPTION came from (DocumentDescriptionSource ordinal:
    -- 0 OCR, 1 user history, 2 CNPJ registry); NULL when there was none.
    SUGGESTED_DESCRIPTION_SOURCE    INTEGER,
    CREATED_AT                      TIMESTAMPTZ NOT NULL DEFAULT now(),
    UPDATED_AT                      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- =====================================================================
-- DOCUMENT_CONFIRMED_ITEMS
-- Written by DocumentConfirmationsRepository when a document is confirmed.
-- Items as confirmed by the user. The suggested ones stay in DOCUMENT_ITEMS.
-- SUGGESTED_ITEM_ID points at the DOCUMENT_ITEMS row the user kept or
-- corrected; NULL means the user added an item the OCR did not read.
-- Suggested items missing here were removed by the user.
-- =====================================================================
CREATE TABLE DOCUMENT_CONFIRMED_ITEMS (
    ID                  BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    DOCUMENT_ID         BIGINT NOT NULL REFERENCES DOCUMENTS(ID),
    SUGGESTED_ITEM_ID   BIGINT REFERENCES DOCUMENT_ITEMS(ID) ON DELETE SET NULL,
    LINE_NUMBER         INTEGER NOT NULL,
    CODE                TEXT,
    DESCRIPTION         TEXT NOT NULL,
    QUANTITY            NUMERIC(12,3) NOT NULL,
    UNIT                TEXT,
    UNIT_PRICE_CENTS    INTEGER NOT NULL,
    TOTAL_CENTS         INTEGER NOT NULL,
    CREATED_AT          TIMESTAMPTZ NOT NULL DEFAULT now(),
    UPDATED_AT          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IX_DOCUMENT_CONFIRMED_ITEMS_DOCUMENT_ID ON DOCUMENT_CONFIRMED_ITEMS(DOCUMENT_ID);

-- =====================================================================
-- NOTIFICATIONS
-- Backs NotificationsEntity / NotificationsRepository.
-- TYPE stores NotificationType ordinal
--   (insight_generated=0, invoice_due=1, goal_reached=2).
-- =====================================================================
CREATE TABLE NOTIFICATIONS (
    ID                 BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    USER_ID            BIGINT NOT NULL REFERENCES USERS(ID),
    TYPE               INTEGER NOT NULL,
    TITLE              TEXT NOT NULL,
    MESSAGE            TEXT NOT NULL,
    RELATED_ENTITY_ID  BIGINT,
    READ_AT            TIMESTAMPTZ,
    CREATED_AT         TIMESTAMPTZ NOT NULL DEFAULT now(),
    UPDATED_AT         TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IX_NOTIFICATIONS_USER_ID ON NOTIFICATIONS(USER_ID);

-- =====================================================================
-- DEVICE_TOKENS
-- Backs DeviceTokensEntity / DeviceTokensRepository.
-- PLATFORM stores DevicePlatform ordinal (android=0, ios=1).
-- =====================================================================
CREATE TABLE DEVICE_TOKENS (
    ID          BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    USER_ID     BIGINT NOT NULL REFERENCES USERS(ID),
    TOKEN       TEXT NOT NULL,
    PLATFORM    INTEGER NOT NULL,
    CREATED_AT  TIMESTAMPTZ NOT NULL DEFAULT now(),
    UPDATED_AT  TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (USER_ID, TOKEN)
);

-- =====================================================================
-- BEHAVIORAL_INSIGHTS
-- Backs BehavioralInsightsEntity / BehavioralInsightsRepository.
-- TYPE and FEEDBACK are stored as text: the app explicitly calls
-- .ToString() on these enums before sending them to Dapper, unlike
-- every other enum-backed column in this schema.
-- =====================================================================
CREATE TABLE BEHAVIORAL_INSIGHTS (
    ID              BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    USER_ID         BIGINT NOT NULL REFERENCES USERS(ID),
    CATEGORY_ID     BIGINT REFERENCES CATEGORIES(ID),
    TYPE            TEXT NOT NULL,
    -- Rule that produced the insight (InsightRuleCodes, e.g. META_ATRASADA) and the
    -- goal/card/bank account/transaction it is about. NULL for insights created
    -- through the API.
    RULE_CODE         TEXT,
    RELATED_ENTITY_ID BIGINT,
    DESCRIPTION     TEXT NOT NULL,
    REFERENCE_DATE  DATE NOT NULL,
    WAS_INTERACTED  BOOLEAN NOT NULL DEFAULT FALSE,
    VIEWED_AT       TIMESTAMPTZ,
    FEEDBACK        TEXT,
    ACTION_TAKEN    BOOLEAN,
    -- Marca que a rotina de ActionTaken (Etapa D) já processou este insight, mesmo quando
    -- o resultado é NULL por conflito de janelas sobrepostas - evita reprocessamento
    -- indefinido pelo job em lote (ver IActionTakenBatchCalculator).
    ACTION_TAKEN_EVALUATED_AT TIMESTAMPTZ,
    -- Numbers sent to the LLM, one per line. Compared after a transaction
    -- changes to detect that the analysis no longer matches the data.
    FACTS           TEXT,
    -- Set when the insight stopped reflecting the user's data (numbers changed
    -- or the rule no longer applies; OUTDATED_REASON = dados_alterados |
    -- nao_se_aplica). The row is kept for ViewedAt/ActionTaken and a new
    -- insight is generated in its place.
    OUTDATED_AT     TIMESTAMPTZ,
    OUTDATED_REASON TEXT,
    CREATED_AT      TIMESTAMPTZ NOT NULL DEFAULT now(),
    UPDATED_AT      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IX_BEHAVIORAL_INSIGHTS_USER_ID ON BEHAVIORAL_INSIGHTS(USER_ID);

-- Dedupe key of the insight jobs: UserId + RuleCode + RelatedEntityId +
-- CategoryId + reference period, among current (not outdated) insights.
CREATE UNIQUE INDEX UX_BEHAVIORAL_INSIGHTS_RULE_DEDUPE
    ON BEHAVIORAL_INSIGHTS (USER_ID, RULE_CODE, COALESCE(RELATED_ENTITY_ID, 0), COALESCE(CATEGORY_ID, 0), REFERENCE_DATE)
    WHERE RULE_CODE IS NOT NULL AND OUTDATED_AT IS NULL;

-- =====================================================================
-- WEEKLY_PROFILE_METRICS
-- Backs WeeklyProfileMetricEntity / WeeklyProfileMetricRepository.
-- =====================================================================
CREATE TABLE WEEKLY_PROFILE_METRICS (
    ID                                    BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    USER_ID                               BIGINT NOT NULL REFERENCES USERS(ID),
    WEEK_REFERENCE                        TEXT NOT NULL,
    TOTAL_EXPENSES_CENTS                  INTEGER NOT NULL DEFAULT 0,
    TOTAL_REVENUE_CENTS                   INTEGER NOT NULL DEFAULT 0,
    PERCENTAGE_EXPENSE_RELATIVE_REVENUE   NUMERIC(9,3) NOT NULL DEFAULT 0,
    QUANTITY_LATE_TRANSACTIONS            INTEGER NOT NULL DEFAULT 0,
    QUANTITY_INSIGHTS_GENERATED           INTEGER NOT NULL DEFAULT 0,
    QUANTITY_INSIGHTS_INTERACTED          INTEGER NOT NULL DEFAULT 0,
    CREATED_AT                            TIMESTAMPTZ NOT NULL DEFAULT now(),
    UPDATED_AT                            TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (USER_ID, WEEK_REFERENCE)
);

-- =====================================================================
-- CNPJ_ACTIVITIES
-- Cache of the public registry lookup (BrasilAPI): main activity (CNAE,
-- 7 digits) and names (trade and legal) of each CNPJ read in a receipt, so
-- each CNPJ is looked up once.
-- CNAE is NULL when the registry does not know the CNPJ.
-- =====================================================================
CREATE TABLE CNPJ_ACTIVITIES (
    CNPJ                TEXT PRIMARY KEY,
    CNAE                INTEGER,
    DESCRIPTION         TEXT,
    TRADE_NAME          TEXT,
    LEGAL_NAME          TEXT,
    FETCHED_AT          TIMESTAMPTZ NOT NULL DEFAULT now()
);
